// Package catalog holds the catalog of kinds, such as boat types. Kinds are
// data: code reads their properties, never their names. The data and its types
// are generated by tools/catalog from shared/; never edit them by hand.
package catalog

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"errors"
	"fmt"
	"io"

	"github.com/daneelvt/keel-over-the-edge/internal/physics"
	"github.com/daneelvt/keel-over-the-edge/internal/sky"
)

//go:embed catalog.gen.json
var embedded []byte

// Load decodes the catalog built into the binary.
func Load() (*Catalog, error) {
	return Parse(embedded)
}

// Parse decodes a catalog strictly: unknown fields and trailing data are
// errors, so a server never runs with data it does not understand.
func Parse(data []byte) (*Catalog, error) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.DisallowUnknownFields()
	var c Catalog
	if err := dec.Decode(&c); err != nil {
		return nil, fmt.Errorf("catalog: %w", err)
	}
	if _, err := dec.Token(); !errors.Is(err, io.EOF) {
		return nil, errors.New("catalog: unexpected data after the catalog")
	}
	if len(c.Boats) == 0 {
		return nil, errors.New("catalog: no boats")
	}
	return &c, nil
}

// Prepare readies the catalog for the physics: the sea's waves, and every
// kind of boat in the catalog's order, each prepared for those waves.
func (c *Catalog) Prepare() (*physics.Waves, []physics.Prepared) {
	sea := SeaParams(c)
	waves := new(physics.Waves)
	physics.PrepareSea(&sea, waves)
	kinds := make([]physics.Prepared, len(c.Boats))
	for i := range c.Boats {
		p := PhysicsParams(&c.Boats[i])
		physics.Prepare(&p, waves, &kinds[i])
	}
	return waves, kinds
}

// PrepareSky readies the catalog's sky for the rule that says where the
// sun, the moon and the stars stand.
func (c *Catalog) PrepareSky() *sky.Prepared {
	p := SkyParams(c)
	s := new(sky.Prepared)
	sky.Prepare(&p, s)
	return s
}

// PrepareWeather readies the catalog's wind for the physics.
func (c *Catalog) PrepareWeather() *physics.WeatherPrepared {
	p := WeatherParams(c)
	w := new(physics.WeatherPrepared)
	physics.PrepareWeather(&p, w)
	for i, k := range SystemKinds(c) {
		w.SetKind(int32(i), &k)
	}
	clouds := CloudParams(c)
	w.PrepareClouds(&clouds)
	for i := range c.Weather.Regimes {
		w.SetRegimeCumulus(int32(i), c.Weather.Regimes[i].Cumulus)
	}
	vis := VisibilityParams(c)
	w.PrepareVisibility(&vis)
	fc := ForecastParams(c)
	w.PrepareForecast(&fc)
	return w
}

// ForecastParams returns the catalog's forecast as the physics package's
// ForecastParams.
func ForecastParams(c *Catalog) physics.ForecastParams {
	f := &c.Weather.Forecast
	return physics.ForecastParams{
		Every: f.Every, Horizon: f.Horizon, Step: f.Step,
		PerHour: f.Cone.PerHour, Forming: f.Cone.Forming, Front: f.Cone.Front,
		Direction: f.Spell.Direction, Speed: f.Spell.Speed,
		GaleMean: f.Gale.Mean, GaleGust: f.Gale.Gust, Quantile: f.Gale.Quantile, Grid: f.Gale.Grid, Within: f.Gale.Within,
	}
}

// VisibilityParams returns the catalog's visibility and lightning as the
// physics package's VisibilityParams: the weather's, with the world's
// clear air, dome and mist band.
func VisibilityParams(c *Catalog) physics.VisibilityParams {
	v, l := &c.Weather.Visibility, &c.Weather.Lightning
	p := physics.VisibilityParams{
		Contrast: v.Contrast, Clear: c.World.Lights.ClearAir * nauticalMile, Dome: c.World.Handout.Dome,
		MistBand: c.World.Disk.Mist * nauticalMile, MistLip: c.World.Disk.Radius,
		MistRange: c.World.Edge.Mist.Range, MistHeight: c.World.Edge.Mist.Height,
		Slot: float64(l.Slot), Sea: l.Sea, Single: l.Single, Strokes: float64(l.Most), Apart: l.Apart,
	}
	copy(p.Words[:], v.Words)
	return p
}

// nauticalMile is a nautical mile, m.
const nauticalMile = 1852

// SystemKinds returns the catalog's kinds of weather system as the physics
// package's SystemKind, in the catalog's order.
func SystemKinds(c *Catalog) []physics.SystemKind {
	shapes := map[Shape]float64{ShapeNone: physics.ShapeNone, ShapeDome: physics.ShapeDome, ShapeLow: physics.ShapeLow}
	inward := map[Inward]float64{InwardNone: physics.InwardNone, InwardWeak: physics.InwardWeak, InwardGone: physics.InwardGone}
	forms := map[CloudForm]float64{
		CloudFormNone: physics.FormNone, CloudFormFog: physics.FormFog, CloudFormCumulus: physics.FormCumulus,
		CloudFormCumulonimbus: physics.FormCumulonimbus, CloudFormStorm: physics.FormStorm,
	}
	out := make([]physics.SystemKind, len(c.Weather.Systems))
	for i, k := range c.Weather.Systems {
		out[i] = physics.SystemKind{
			Shape: shapes[k.Shape], Turning: k.Turning, Width: k.Width, Ahead: k.Ahead,
			Broad: k.Broad[0], BroadWidth: k.Broad[1], Stretch: k.Stretch, Inward: inward[k.Inward], Gusts: k.Gusts,
		}
		o := &out[i]
		if s := k.Swell; s != nil {
			copy(o.SwellPeriod[:], s.Period)
			copy(o.SwellBand[:], s.Band)
			copy(o.SwellHeight[:], s.Height)
			copy(o.SwellWind[:], k.Wind)
		}
		cl := &k.Cloud
		o.CloudForm = forms[cl.Form]
		o.CloudBase, o.CloudTop = cl.Base, cl.Top
		copy(o.CloudReach[:], cl.Reach)
		copy(o.CloudDeck[:], cl.Deck)
		o.CloudLead, o.CloudDark = cl.Lead, cl.Dark
		if s := cl.Sheets; s != nil {
			copy(o.SheetCirrus[:], s.Cirrus)
			copy(o.SheetMiddle[:], s.Middle)
			copy(o.SheetLow[:], s.Low)
		}
		o.RainRate, o.RainWidth = k.Rain.Rate, k.Rain.Width
		o.RainBands, o.RainTurn = float64(k.Rain.Bands), k.Rain.Turn
		if f := k.Fog; f != nil {
			copy(o.FogCore[:], f.Core)
			o.FogHeight = f.Height
		}
		if l := k.Lightning; l != nil {
			o.LightningAbove, o.LightningRate = l.Above, l.Rate
			copy(o.LightningWithin[:], l.Within)
		}
	}
	return out
}

// PrepareEncounters readies the catalog's encounters for the physics: how
// boats touch, take each other's wind and are judged by the Articles.
func (c *Catalog) PrepareEncounters() *physics.EncounterPrepared {
	p := EncounterParams(c)
	e := new(physics.EncounterPrepared)
	physics.PrepareEncounters(&p, e)
	return e
}
